<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evaluaciones - Learning Lab</title><link rel="stylesheet" href="../../../assets/css/admin.css"></head><body><?php include '../../includes/sidebar.php'; ?><div class="admin-main"><?php include '../../includes/navbar.php'; ?><section class="admin-content learning-admin-page"><div class="gestion-header"><div><span class="learning-admin-kicker">Learning Lab</span><h1>Evaluaciones</h1><p class="dashboard-subtitle">Configura el examen final de cada curso, la nota mínima y los intentos.</p></div></div><div class="admin-table-wrapper"><table class="admin-table learning-action-table"><thead><tr><th>Curso</th><th>Evaluación</th><th>Preguntas</th><th>Nota mínima</th><th>Intentos</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><strong><?php echo learningH($i['curso']); ?></strong></td><td><?php echo $i['id_evaluacion']?learningH($i['titulo']):'<span class="learning-muted">Sin evaluación</span>'; ?></td><td><?php echo (int)$i['total_preguntas']; ?></td><td><?php echo $i['id_evaluacion']?round((float)$i['nota_minima']).'%':'—'; ?></td><td><?php echo $i['id_evaluacion']?(int)$i['intentos_permitidos']:'—'; ?></td><td><?php if($i['id_evaluacion']): ?><span class="learning-badge <?php echo learningEstadoClase($i['estado']); ?>"><?php echo learningEstadoTexto($i['estado']); ?></span><?php else: ?>—<?php endif; ?></td><td><a class="btn-editar" href="editar.php?curso=<?php echo (int)$i['id_curso']; ?>"><?php echo $i['id_evaluacion']?'Gestionar':'Crear examen'; ?></a></td></tr><?php endforeach; ?></tbody></table></div></section></div></body></html>
